const std = @import("std");

pub fn main() !void {
    const graph = [_][5]u8{
        [_]u8{ 0, 1, 1, 0, 0 },
        [_]u8{ 1, 0, 0, 1, 0 },
        [_]u8{ 1, 0, 0, 1, 1 },
        [_]u8{ 0, 1, 1, 0, 0 },
        [_]u8{ 0, 0, 1, 0, 0 },
    };
    var visited = [_]bool{false} ** 5;
    var queue: [5]u8 = undefined;
    var front: usize = 0;
    var rear: usize = 0;

    const start: u8 = 0;
    visited[start] = true;
    queue[rear] = start;
    rear += 1;

    while (front < rear) {
        const node = queue[front];
        front += 1;
        std.debug.print("{} ", .{node});
        for (0..5) |neighbor| {
            if (graph[node][neighbor] == 1 and !visited[neighbor]) {
                visited[neighbor] = true;
                queue[rear] = @intCast(neighbor);
                rear += 1;
            }
        }
    }
    std.debug.print("\n", .{});
}
